      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\">\n                    <rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/>\n                    <text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">THE SEVEN-LESSON SYSTEM</text>\n                    <text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">One architecture, seven layers</text>\n                    <rect x=\"100\" y=\"160\" width=\"900\" height=\"100\" rx=\"15\" fill=\"rgba(99,102,241,0.12)\" stroke=\"#6366f1\" stroke-width=\"2\"/>\n                    <text x=\"160\" y=\"200\" text-anchor=\"start\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"20\">L1 OBSERVATION</text>\n                    <text x=\"160\" y=\"238\" text-anchor=\"start\" fill=\"#fff\" font-size=\"17\">Calibrate the observer — see what's actually there</text>\n                    <rect x=\"100\" y=\"272\" width=\"900\" height=\"100\" rx=\"15\" fill=\"rgba(139,92,246,0.12)\" stroke=\"#8b5cf6\" stroke-width=\"2\"/>\n                    <text x=\"160\" y=\"312\" text-anchor=\"start\" fill=\"#8b5cf6\" font-weight=\"bold\" font-size=\"20\">L2 FACT vs INFERENCE</text>\n                    <text x=\"160\" y=\"350\" text-anchor=\"start\" fill=\"#fff\" font-size=\"17\">Sort the established from the leapt-to</text>\n                    <rect x=\"100\" y=\"384\" width=\"900\" height=\"100\" rx=\"15\" fill=\"rgba(236,72,153,0.12)\" stroke=\"#ec4899\" stroke-width=\"2\"/>\n                    <text x=\"160\" y=\"424\" text-anchor=\"start\" fill=\"#ec4899\" font-weight=\"bold\" font-size=\"20\">L3 ASSUMPTIONS</text>\n                    <text x=\"160\" y=\"462\" text-anchor=\"start\" fill=\"#fff\" font-size=\"17\">What must be true? Who chose this frame?</text>\n                    <rect x=\"100\" y=\"496\" width=\"900\" height=\"100\" rx=\"15\" fill=\"rgba(20,184,166,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/>\n                    <text x=\"160\" y=\"536\" text-anchor=\"start\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"20\">L4 SOURCES &amp; EVIDENCE</text>\n                    <text x=\"160\" y=\"574\" text-anchor=\"start\" fill=\"#fff\" font-size=\"17\">Grade the messenger before weighing the message</text>\n                    <rect x=\"100\" y=\"608\" width=\"900\" height=\"100\" rx=\"15\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/>\n                    <text x=\"160\" y=\"648\" text-anchor=\"start\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"20\">L5 ARGUMENT ANALYSIS</text>\n                    <text x=\"160\" y=\"686\" text-anchor=\"start\" fill=\"#fff\" font-size=\"17\">Claim-reasons-evidence; validity and soundness</text>\n                    <rect x=\"100\" y=\"720\" width=\"900\" height=\"100\" rx=\"15\" fill=\"rgba(245,158,11,0.12)\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n                    <text x=\"160\" y=\"760\" text-anchor=\"start\" fill=\"#f59e0b\" font-weight=\"bold\" font-size=\"20\">L6 FALLACIES</text>\n                    <text x=\"160\" y=\"798\" text-anchor=\"start\" fill=\"#fff\" font-size=\"17\">Detect the counterfeits — especially your own</text>\n                    <rect x=\"100\" y=\"832\" width=\"900\" height=\"100\" rx=\"15\" fill=\"rgba(239,68,68,0.1)\" stroke=\"#ef4444\" stroke-width=\"2\"/>\n                    <text x=\"160\" y=\"872\" text-anchor=\"start\" fill=\"#ef4444\" font-weight=\"bold\" font-size=\"20\">L7 DEPLOYMENT</text>\n                    <text x=\"160\" y=\"910\" text-anchor=\"start\" fill=\"#fff\" font-size=\"17\">The whole system at feed speed: workflow + rubric</text>\n                    <rect x=\"100\" y=\"960\" width=\"900\" height=\"90\" rx=\"15\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/>\n                    <text x=\"550\" y=\"998\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"22\">THE THREAD: THE DISCIPLINE OF DELAY</text>\n                    <text x=\"550\" y=\"1032\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">A gap between stimulus and belief — keep it open</text>\n                </svg>",
